#!/usr/bin/env python3
from pathlib import Path
import shutil

path = Path("src/conditional_prior_residual.py")
if not path.exists():
    raise SystemExit(
        "ERROR: 请在项目根目录 ~/project 执行；"
        "未找到 src/conditional_prior_residual.py"
    )

text = path.read_text(encoding="utf-8")

if "raman_variance_equalization_enabled" in text:
    raise SystemExit(
        "ERROR: 检测到D4.21代码已经存在。"
        "为避免重复修改，本脚本停止。"
    )

backup = Path("/tmp/conditional_prior_residual.before_d4_21.py")
shutil.copy2(path, backup)

def replace_once(old: str, new: str, name: str) -> None:
    global text
    count = text.count(old)
    if count != 1:
        raise RuntimeError(
            f"{name}没有唯一匹配：匹配数量={count}。"
            "源文件未写回，请不要继续训练。"
        )
    text = text.replace(old, new, 1)

replace_once('@dataclass\nclass ConditionalPriorEntry:\n    valid_length: int\n    number_of_training_spectra: int\n    outer: PriorResidualTransformer\n    broad_local: BroadLocalResidualDecomposer\n', '@dataclass\nclass ConditionalPriorEntry:\n    valid_length: int\n    number_of_training_spectra: int\n    outer: PriorResidualTransformer\n    broad_local: BroadLocalResidualDecomposer\n    # D4.21: train-only, condition-specific Raman-wise variance\n    # equalization applied AFTER the existing robust-asinh local transform.\n    # None means legacy D4.2--D4.20 behavior.\n    raman_variance_multiplier: np.ndarray | None = None\n    raman_variance_floor: float = 0.0\n    raman_variance_reference_scale: float = 1.0\n', 'dataclass')

